import re

def parse(lines):
    blocks = []
    skip = []
    cur = None
    for i, l in enumerate(lines):
        if not l.strip():
            continue
        m = re.match(r'^Available (\S+) for this target:\s*$', l)
        if m:
            cur = {"name": m.group(1).lower(), "kind": "table", "lines": [], "records": []}
            blocks.append(cur)
            skip.append(i)
            continue
        m = re.match(r'^\s+(?P<name>\S+)\s+-\s+(?P<desc>.*?)\s*$', l)
        if m and cur is not None:
            cur["lines"].append(i)
            cur["records"].append({"name": m.group('name'), "description": m.group('desc')})
            continue
        skip.append(i)
    return {"blocks": blocks, "skip": skip}
